import unicodedata


def identity_key(username):
    """Return the canonical key used to compare usernames."""
    trimmed = username.strip()
    # casefold implements Unicode caseless matching (unlike lower).  NFC keeps
    # canonically equivalent spellings of the same Unicode text together.
    return unicodedata.normalize(
        "NFC", unicodedata.normalize("NFC", trimmed).casefold()
    )

