"""Shared helpers for normalizing user-supplied usernames.

Usernames are treated as case-insensitive and insensitive to surrounding
whitespace everywhere they are used as identity keys (registration,
authentication, directory lookup). ``casefold`` is used instead of
``lower`` so that Unicode usernames (e.g. "Straße" vs "STRASSE") are
compared correctly.
"""


def display_name(username):
    """Return the trimmed, display-friendly form of a username."""
    return username.strip()


def normalize_key(username):
    """Return the case- and whitespace-insensitive identity key."""
    return display_name(username).casefold()

